// Open a deck in the 2D reference engine (built with OPENSWMM_HAS_2D, build2d) through its
// C API, then dump the engine's SimulationContext, the SWMMEngine members open() sets, and the
// 2D router's open-time state (twoddump.hpp, generated by tools/ctxdump.py). The C API handle
// IS the SWMMEngine; `#define private public` (after every standard header, so their access
// specifiers are untouched) lets the harness read the router's private members. Compile with
// the engine's own layout defines plus the 2D one: -DNDEBUG -DSWMM_OS_LINUX -DSWMM_USE_OPENMP
// -fopenmp -DOPENSWMM_HAS_2D=1, against build2d's library (gate/build.sh ctxopen2d).
// The Rust twin is crates/engine/examples/ctxopen2d.rs (feature twod).
// Usage: ctxopen2d deck.inp [open|lenient|metadata]
//   open      swmm_engine_open(deck, "/dev/null", "/dev/null", NULL)   (the default)
//   lenient   the same after swmm_engine_set_lenient_open(e, 1)
//   metadata  swmm_engine_open_metadata(deck)
#include <any>
#include <bitset>
#include <chrono>
#include <filesystem>
#include <list>
#include <set>
#include <span>
#include <unordered_set>
#include <random>
#include <shared_mutex>
#include <atomic>
#define private public
#define protected public
#include "openswmm/engine/openswmm_engine.h"
#include "core/SWMMEngine.hpp"
#define CTXDUMP_ENGINE
#include "ctxdump.hpp"
#include "twoddump.hpp"
int main(int argc, char** argv) {
    if (argc < 2)
        return 2;
    const char* mode = argc > 2 ? argv[2] : "open";
    SWMM_Engine e = swmm_engine_create();
    if (std::strcmp(mode, "lenient") == 0)
        swmm_engine_set_lenient_open(e, 1);
    int rc = std::strcmp(mode, "metadata") == 0 ? swmm_engine_open_metadata(e, argv[1])
                                                : swmm_engine_open(e, argv[1], "/dev/null", "/dev/null", nullptr);
    std::printf("open_rc %d\n", rc);
    auto* eng = static_cast<openswmm::SWMMEngine*>(e);
    ctxdump::dump(eng->context());
    ctxdump::engdump(*eng);
    ctxdump::twoddump(*eng);
    return 0;
}
